class FileUploadWidget {
  constructor(container, onUploadSuccess) {
    this.container = container;
    this.onUploadSuccess = onUploadSuccess;
    this.render();
  }
  render() {
    this.input = document.createElement('input');
    this.input.type = 'file';
    this.input.addEventListener('change', (e) => this.handleUpload(e));
    this.container.appendChild(this.input);
  }
  async handleUpload(e) {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    const res = await fetch('/wp-json/tsp/v1/upload', { method: 'POST', body: formData });
    const data = await res.json();
    if (data.success) this.onUploadSuccess(data.file);
  }
}
export default FileUploadWidget;

